def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    result = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                raise ValueError("Unbalanced parentheses")
            stack.pop()
        elif char.isspace():
            continue
        else:
            raise ValueError(f"Invalid character '{char}' in input string")
    if stack:
        raise ValueError("Unbalanced parentheses")
    while stack:
        result.append(stack.pop())
    return result

